fn authorize_default(
    cwd: &std::path::Path,
    placement_entry: &str,
    activation_record: &str,
    expected_head: Option<&str>,
) -> JsonValue {
    let mut args = default_args("authorize");
    args.extend([
        "--node-id",
        NODE,
        "--placement-entry",
        placement_entry,
        "--activation-record",
        activation_record,
    ]);
    if let Some(expected) = expected_head {
        args.extend(["--expected-head", expected]);
    }
    args.extend(["--format", "json"]);
    run_json(cwd, args)
}

fn inspect_default(cwd: &std::path::Path) -> JsonValue {
    let mut args = default_args("inspect");
    args.extend(["--format", "json"]);
    run_json(cwd, args)
}

fn invoke_default(cwd: &std::path::Path, input: &str) -> JsonValue {
    let mut args = default_args("invoke");
    args.extend(["--input", input, "--format", "json"]);
    run_json(cwd, args)
}

fn advance_placement(cwd: &std::path::Path, module: &str, expected: Option<&str>) -> JsonValue {
    let mut args = vec![
        "program",
        "module",
        "foreign-process",
        "placement",
        "advance",
        "--slot",
        SLOT,
        "--node-id",
        NODE,
        "--module-cid",
        module,
    ];
    if let Some(expected) = expected {
        args.extend(["--expected-head", expected]);
    }
    args.extend(["--format", "json"]);
    run_json(cwd, args)
}

